'use strict';
let S, page='overview', query='', jobFilter='All', dispatchDate='', dispatchMode='board', customerFilter='Active';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const usd=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(v/100);
const initials=v=>v.split(/\s+/).map(i=>i[0]).slice(0,2).join('').toUpperCase();
const fmt=(d,opts={month:'short',day:'numeric'})=>d?new Date(/(?:Z|[+-]\d\d:\d\d)$/.test(d)?d:d.slice(0,10)+'T12:00:00Z').toLocaleDateString('en-US',{...opts,timeZone:'America/Los_Angeles'}):'—';
const time=d=>{const [h,m]=d.slice(11,16).split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`};
const cid=id=>S.customers.find(c=>c.id===Number(id));
const tid=id=>S.technicians.find(t=>t.id===Number(id));
const match=v=>!query||String(v).toLowerCase().includes(query.toLowerCase());
const badge=v=>`<span class="badge ${esc(v.replaceAll(' ','-'))}">${esc(v)}</span>`;
const btn=(text,act,id='',cls='')=>`<button type="button" class="btn ${cls}" data-act="${act}" data-id="${esc(id)}">${text}</button>`;
const empty=(title='Nothing here yet',text='Create your first record to get started.')=>`<div class="empty"><strong>${esc(title)}</strong>${esc(text)}</div>`;
const avatar=(name,cls='')=>`<span class="avatar ${cls}">${esc(initials(name))}</span>`;
const person=id=>{const c=cid(id);return c?`<div class="person">${avatar(c.name)}<div><strong>${esc(c.name)}</strong><small>${esc(c.phone)}</small></div></div>`:'—'};
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const panel=(title,sub,body,action='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`;
const head=(title,sub,actions='',eyebrow='YOUR WORK, IN ORDER')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="btns">${actions}</div></div>`;
const metric=(label,value,foot,symbol='↗')=>`<article class="metric"><div class="metric-label">${label}<span>${symbol}</span></div><div class="metric-number">${value}</div><div class="metric-foot">${foot}</div></article>`;
const option=(v,label,selected)=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(label)}</option>`;
const field=(label,name,type='text',value='',attrs='',full=false)=>`<label class="field ${full?'full':''}">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${attrs}></label>`;
const select=(label,name,options,full=false)=>`<label class="field ${full?'full':''}">${label}<select name="${name}">${options}</select></label>`;
const textArea=(label,name,value='',required=false)=>`<label class="field full">${label}<textarea name="${name}" maxlength="4000" ${required?'required':''}>${esc(value)}</textarea></label>`;
const customers=(selected,all=false)=>S.customers.filter(c=>all||c.active||c.id===Number(selected)).map(c=>option(c.id,c.name,selected)).join('');
const customerSelect=(selected)=>select('Customer','customer_id',customers(selected));
const totalPaid=i=>S.payments.filter(p=>p.invoice_id===i.id).reduce((n,p)=>n+p.amount,0);
const balance=i=>i.total-totalPaid(i);
const invStatus=i=>balance(i)>0&&i.due<S.today?'Overdue':i.status;
const nextStatus=j=>['Scheduled','En route','In progress','Completed'][['Scheduled','En route','In progress','Completed'].indexOf(j.status)+1];
const activityName=a=>a.split('/').map(x=>x.replaceAll('_',' ')).join(' · ');
function toast(message,failure=false){const t=$('#toast');t.textContent=message;t.className='show'+(failure?' failure':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',4500)}
async function api(route,data){const r=await fetch('/api/'+route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw Error(j.error||'Request failed.');return j}
async function load(){const r=await fetch('/api/state');if(!r.ok)throw Error('Cannot load workspace.');S=await r.json();if(!dispatchDate){const days=[...new Set(S.jobs.map(j=>j.start.slice(0,10)))].sort();dispatchDate=days.find(d=>d>=S.today)||days.at(-1)||S.today;}$('.workspace strong').textContent=S.settings[0].company;render()}
function setPage(){page=location.hash.slice(1)||'overview';if(!$(`nav [data-page="${CSS.escape(page)}"]`))page='overview';query='';$('#search').value='';document.body.classList.remove('menu-open');if(S)render()}
function render(){ $$('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#crumb').textContent=$(`nav [data-page="${page}"]`).lastChild.textContent.trim();const views={overview,dispatch,customers:customerPage,requests:requestPage,estimates:estimatePage,invoices:invoicePage,agreements:agreementPage,equipment:equipmentPage,pricebook:pricebookPage,team:teamPage,tasks:taskPage,timesheets:timesheetPage,expenses:expensePage,inventory:inventoryPage,reports:reportPage,settings:settingsPage};$('#content').innerHTML=views[page]();$('.search').style.visibility=['settings','reports'].includes(page)?'hidden':'visible';}

function jobRows(jobs){return jobs.map(j=>`<tr class="clickable" tabindex="0" role="button" data-act="job" data-id="${j.id}"><td><strong>${esc(j.title)}</strong><small>JOB-${String(j.id).padStart(4,'0')} · ${esc(cid(j.customer_id).name)}</small></td><td><strong>${time(j.start)}</strong><small>${fmt(j.start)} · ${time(j.end)}</small></td><td><div class="person">${avatar(tid(j.technician_id).name,'blue')}<span>${esc(tid(j.technician_id).name.split(' ')[0])}</span></div></td><td>${badge(j.status)}</td><td><span class="priority ${j.priority}">${j.priority}</span></td></tr>`)}
function taskRows(tasks){return tasks.map(t=>`<div class="todo ${t.done?'done':''}"><button class="check" aria-label="${t.done?'Reopen':'Complete'} ${esc(t.title)}" data-act="task-toggle" data-id="${t.id}">${t.done?'✓':''}</button><div><strong>${esc(t.title)}</strong><small>${t.customer_id?esc(cid(t.customer_id).name)+' · ':''}${fmt(t.due)}</small></div></div>`).join('')}
function overview(){
 const todayJobs=S.jobs.filter(j=>j.start.startsWith(S.today)&&j.status!=='Canceled');
 const filtered=todayJobs.filter(j=>(jobFilter==='All'||j.status===jobFilter)&&match(j.title+' '+cid(j.customer_id).name));
 const received=S.payments.filter(p=>p.created.startsWith(S.today)).reduce((n,p)=>n+p.amount,0);
 const outstanding=S.invoices.reduce((n,i)=>n+balance(i),0);
 const due=S.equipment.filter(e=>e.next_service<=S.today).length;
 const jobs=panel("Today's schedule",`${todayJobs.length} visits. One well-organized day.`,
 `<div class="tabs">${['All','Scheduled','En route','In progress','Completed'].map(v=>`<button data-act="job-filter" data-id="${v}" class="${jobFilter===v?'active':''}">${v}<span class="count">${v==='All'?todayJobs.length:todayJobs.filter(j=>j.status===v).length}</span></button>`).join('')}</div>`+
 (filtered.length?table(['JOB / CUSTOMER','TIME','TECHNICIAN','STATUS','PRIORITY'],jobRows(filtered)):empty('A little breathing room','No visits match this view.')+(todayJobs.length===0&&S.jobs.length?`<div class="panel-body">${btn('View latest scheduled day','dispatch-latest','','small')}</div>`:''))+`<div class="table-end">All appointments shown in Pacific time</div>`, `<a class="link" href="#dispatch">Open dispatch ↗</a>`);
 return head('A little clarity for your day.',"Good service starts with a team that knows what's next.",`<span class="calendar-mini">▦ &nbsp; ${fmt(S.today,{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</span>${btn('+ New request','request-new','','primary')}`,esc(S.settings[0].company.toUpperCase())+' / OPERATIONS OVERVIEW')+
 `<div class="metrics">${metric("Today's visits",todayJobs.length,`<strong>${todayJobs.filter(j=>j.status==='Completed').length} completed</strong> · keeping things moving`,'▦')}${metric('Payments received',usd(received),'Recorded today · no live card processing','$')}${metric('Outstanding balance',usd(outstanding),`${S.invoices.filter(i=>balance(i)>0).length} invoices awaiting payment`,'↗')}${metric('Service due',due,`${S.equipment.length} pieces of equipment tracked`,'↻')}</div>`+
 `<div class="content-grid"><div>${jobs}<div class="bottom-grid">${panel('On the horizon','Maintenance worth getting ahead of.',S.equipment.slice().sort((a,b)=>a.next_service.localeCompare(b.next_service)).slice(0,3).map(e=>`<div class="equipment-line"><div><strong>${esc(e.brand)} ${esc(e.kind)}</strong><small>${esc(cid(e.customer_id).name)}</small></div>${badge(e.next_service<S.today?'Overdue':fmt(e.next_service))}</div>`).join(''),'<a class="link" href="#equipment">View all ↗</a>')}${panel('Recent activity','A shared view of what changed.',`<div class="panel-body">${S.activities.slice(-4).reverse().map(a=>`<div class="activity-row">${esc(activityName(a.action))}<small>Record #${a.record_id} · ${fmt(a.created)}</small></div>`).join('')||'<p class="muted">Changes you make appear here. Ready when you are.</p>'}</div>`)}</div></div><aside class="right-rail"><div class="welcome-card"><div class="eyebrow">A BETTER KIND OF BUSY</div><h2>More comfort.<br>Less chaos.</h2><p>Everything your service team needs, all in one place.</p><span class="welcome-art">✳</span></div>${panel('Your field team','Ready for the next call.',S.technicians.filter(t=>t.active).map((t,i)=>`<div class="team-line">${avatar(t.name,['','blue','rose'][i%3])}<div><strong>${esc(t.name)}</strong><small>${esc(t.specialty)}</small></div><span class="tag">${todayJobs.filter(j=>j.technician_id===t.id).length} visits</span></div>`).join(''),'<a class="link" href="#team">↗</a>')}${panel('Small things, big difference','Your follow-up list.',taskRows(S.tasks.filter(t=>!t.done).slice(0,4))||empty('All caught up','Your follow-ups are complete.'),btn('+','task-new','','small'))}</aside></div>`;
}
function dispatch(){const jobs=S.jobs.filter(j=>j.start.startsWith(dispatchDate)&&match(j.title+' '+cid(j.customer_id).name+' '+tid(j.technician_id).name)&&(jobFilter==='All'||j.status===jobFilter));
 return head('A place for every visit.','Dispatch with confidence. Keep your team and your customers in sync.',btn('+ Schedule visit','schedule-new','','primary'),'FIELD OPERATIONS / DISPATCH')+
 `<div class="toolbar"><div class="filter-set"><input type="date" id="dispatch-date" aria-label="Dispatch date" value="${dispatchDate}"><select id="dispatch-status" aria-label="Job status">${['All',...['Scheduled','En route','In progress','Completed','Canceled']].map(v=>option(v,v==='All'?'All statuses':v,jobFilter)).join('')}</select>${btn('Today','dispatch-today','','small')}</div><div class="segment">${['board','list'].map(v=>`<button data-act="dispatch-mode" data-id="${v}" class="${dispatchMode===v?'active':''}">${v==='board'?'▦ Board':'≡ List'}</button>`).join('')}</div></div>`+
 (dispatchMode==='list'?panel('Service visits',`${jobs.length} visits on ${fmt(dispatchDate)}`,jobs.length?table(['JOB / CUSTOMER','TIME','TECHNICIAN','STATUS','PRIORITY'],jobRows(jobs)):empty('No visits scheduled','Approve an estimate, then schedule a visit.')):
 `<div class="dispatch-grid">${S.technicians.filter(t=>t.active||jobs.some(j=>j.technician_id===t.id)).map((t,i)=>`<section class="tech-column"><div class="tech-head">${avatar(t.name,['','blue','rose'][i%3])}<div><h3>${esc(t.name)}</h3><small>${esc(t.specialty)} · ${jobs.filter(j=>j.technician_id===t.id).length} visits</small></div></div>${jobs.filter(j=>j.technician_id===t.id).sort((a,b)=>a.start.localeCompare(b.start)).map(j=>`<article class="job-card ${j.priority}" tabindex="0" role="button" data-act="job" data-id="${j.id}" aria-label="Open ${esc(j.title)}"><header><span>${time(j.start)} – ${time(j.end)}</span><span>JOB-${j.id.toString().padStart(4,'0')}</span></header><h3>${esc(j.title)}</h3><p>${esc(cid(j.customer_id).name)}<br>${esc(jobAddress(j))}</p><footer>${badge(j.status)}<span class="priority ${j.priority}">${j.priority}</span></footer></article>`).join('')||empty('Open schedule','Room for the next service call.')}</section>`).join('')}</div>`);
}
function jobAddress(j){const q=S.quotes.find(q=>q.id===j.quote_id);return S.properties.find(p=>p.id===q?.property_id)?.address||cid(j.customer_id).address}
function customerPage(){const rows=S.customers.filter(c=>(customerFilter==='All'||!!c.active===(customerFilter==='Active'))&&match(c.name+' '+c.email+' '+c.address));return head('Good relationships, well kept.','Every customer, property, and service history in one place.',btn('+ Add customer','customer-new','','primary'),'RELATIONSHIPS / CUSTOMERS')+`<div class="toolbar"><div class="segment">${['Active','Archived','All'].map(v=>`<button data-act="customer-filter" data-id="${v}" class="${customerFilter===v?'active':''}">${v}</button>`).join('')}</div><a class="btn small" href="/api/export?table=customers" download="customers.csv">↓ Export CSV</a></div>`+panel('Customer directory',`${rows.length} customers`,rows.length?table(['CUSTOMER','CONTACT','PROPERTIES','LAST JOB','STATUS'],rows.map(c=>{const j=S.jobs.filter(j=>j.customer_id===c.id).at(-1);return `<tr class="clickable" tabindex="0" role="button" data-act="customer" data-id="${c.id}"><td>${person(c.id)}</td><td>${esc(c.email)}<small>${esc(c.address)}</small></td><td>${S.properties.filter(p=>p.customer_id===c.id).length}</td><td>${j?fmt(j.start):'No visits yet'}</td><td>${badge(c.active?'Active':'Archived')}</td></tr>`})):empty('No customers found','Try another search or add a customer.'))}
function requestPage(){const rows=S.requests.filter(r=>match(r.title+' '+cid(r.customer_id).name+' '+r.status));return head('Turn the first call into the next job.','Capture service requests, follow up, and prepare an estimate.',btn('+ New request','request-new','','primary'),'GROWTH / REQUESTS')+panel('Service requests',`${rows.filter(r=>r.status==='New').length} new requests`,rows.length?table(['REQUEST','CUSTOMER','SOURCE','PRIORITY','STATUS',''],rows.map(r=>`<tr><td><strong>${esc(r.title)}</strong><small>${esc(r.description.slice(0,70))}</small></td><td><button class="link" data-act="customer" data-id="${r.customer_id}">${esc(cid(r.customer_id).name)}</button></td><td>${esc(r.source)}</td><td><span class="priority ${r.priority}">${r.priority}</span></td><td>${badge(r.status)}</td><td>${btn('Open','request',r.id,'small')}</td></tr>`)):empty('No requests yet','Capture your next call here.'))}
function estimatePage(){const rows=S.quotes.filter(q=>match(q.title+' '+cid(q.customer_id).name+' '+q.status));return head('Make the next yes easy.','Clear estimates, itemized pricing, and approvals you can track.',btn('+ New estimate','estimate-new','','primary'),'SALES / ESTIMATES')+`<div class="metrics">${metric('Awaiting approval',rows.filter(q=>q.status==='Draft').length,'Draft estimates · not emailed')}${metric('Open estimate value',usd(rows.filter(q=>q.status==='Draft').reduce((a,q)=>a+q.total,0)),'Potential work in your pipeline')}${metric('Approved estimates',rows.filter(q=>q.status==='Approved').length,'Customer approvals recorded')}${metric('Ready to schedule',rows.filter(q=>q.status==='Approved'&&!S.jobs.some(j=>j.quote_id===q.id)).length,'Approved and waiting for a visit')}</div>`+panel('Your estimates',`${rows.length} estimates`,rows.length?table(['ESTIMATE','CUSTOMER','CREATED','TOTAL','STATUS',''],rows.slice().reverse().map(q=>`<tr class="clickable" tabindex="0" role="button" data-act="estimate" data-id="${q.id}"><td><strong>${esc(q.title)}</strong><small>EST-${String(q.id).padStart(4,'0')}</small></td><td>${esc(cid(q.customer_id).name)}</td><td>${fmt(q.created)}</td><td>${usd(q.total)}</td><td>${badge(q.status)}</td><td>↗</td></tr>`)):empty('No estimates yet','Build an estimate from your price book.'))}
function invoicePage(){const rows=S.invoices.filter(i=>match(cid(i.customer_id).name+' '+invStatus(i)+' '+i.id));return head('Close the loop. Get paid.','Create invoices from completed jobs and track every payment.',btn('Invoice completed job','invoice-new','','primary'),'FINANCES / INVOICES')+`<div class="metrics">${metric('Total invoiced',usd(rows.reduce((n,i)=>n+i.total,0)),'All invoices')}${metric('Payments recorded',usd(S.payments.reduce((n,p)=>n+p.amount,0)),'Manual payment ledger')}${metric('Outstanding',usd(rows.reduce((n,i)=>n+balance(i),0)),'Awaiting payment')}${metric('Overdue',rows.filter(i=>invStatus(i)==='Overdue').length,'Past their payment due date')}</div>`+panel('Invoices','Amounts in USD. Payments are recorded manually.',rows.length?table(['INVOICE','CUSTOMER','DUE','TOTAL','BALANCE','STATUS'],rows.slice().reverse().map(i=>`<tr class="clickable" tabindex="0" role="button" data-act="invoice" data-id="${i.id}"><td><strong>INV-${String(i.id).padStart(4,'0')}</strong><small>${esc(S.jobs.find(j=>j.id===i.job_id).title)}</small></td><td>${esc(cid(i.customer_id).name)}</td><td>${fmt(i.due)}</td><td>${usd(i.total)}</td><td>${usd(balance(i))}</td><td>${badge(invStatus(i))}</td></tr>`)):empty('No invoices yet','Complete a job, then create its invoice.'))}
function agreementPage(){const rows=S.agreements.filter(a=>match(a.name+' '+cid(a.customer_id).name));return head('Comfort, on a recurring basis.','Track service agreements and prepare each maintenance visit when due.',btn('+ Add maintenance plan','agreement-new','','primary'),'RETENTION / MAINTENANCE')+`<div class="panel-grid">${rows.map(a=>`<article class="service-card">${badge(a.status)}<h3>${esc(a.name)}</h3><button class="link" data-act="customer" data-id="${a.customer_id}">${esc(cid(a.customer_id).name)}</button><div class="price">${usd(a.price)}</div><p>Per visit · every ${a.interval_months} months<br>Next visit: <strong>${fmt(a.next_visit)}</strong></p><div class="btns">${a.status==='Active'&&a.next_visit<=S.today?btn('Prepare due visit','agreement-visit',a.id,'primary small'):''}${a.status!=='Canceled'?btn(a.status==='Active'?'Pause':'Resume','agreement-toggle',a.id,'small'):''}${a.status!=='Canceled'?btn('Cancel plan','agreement-cancel',a.id,'small ghost'):''}</div></article>`).join('')||empty('No maintenance plans','Build repeat business with a service agreement.')}</div><p class="help">Preparing a due visit creates an approved estimate and advances the next service date. Choose a technician and time to schedule it. Recurring card charges are not enabled.</p>`}
function equipmentPage(){const rows=S.equipment.filter(e=>match([e.kind,e.brand,e.model,e.serial,cid(e.customer_id).name].join(' ')));return head('Know the system before you arrive.','Equipment details, serial numbers, and upcoming service dates.',btn('+ Add equipment','equipment-new','','primary'),'ASSETS / EQUIPMENT')+panel('Equipment register',`${rows.length} assets`,rows.length?table(['EQUIPMENT','CUSTOMER / PROPERTY','MODEL / SERIAL','NEXT SERVICE',''],rows.map(e=>`<tr><td><strong>${esc(e.brand)} ${esc(e.kind)}</strong></td><td><button class="link" data-act="customer" data-id="${e.customer_id}">${esc(cid(e.customer_id).name)}</button><small>${esc(S.properties.find(p=>p.id===e.property_id)?.label||'Primary property')}</small></td><td>${esc(e.model)}<small>${esc(e.serial)}</small></td><td>${e.next_service<S.today?badge('Overdue'):''} ${fmt(e.next_service)}</td><td>${btn('Update service date','equipment-service',e.id,'small')}</td></tr>`)):empty('No equipment found','Add a unit to its customer record.'))}
function pricebookPage(){const rows=S.pricebook.filter(p=>p.active&&match(p.name+' '+p.category));return head('Your expertise, consistently priced.','A reusable catalog of labor, parts, and common HVAC services.',btn('+ Add service','pricebook-new','','primary'),'OPERATIONS / PRICE BOOK')+panel('Services & parts',`${rows.length} active items`,rows.length?table(['SERVICE / ITEM','CATEGORY','UNIT PRICE',''],rows.map(p=>`<tr><td><strong>${esc(p.name)}</strong></td><td>${badge(p.category)}</td><td>${usd(p.unit_cents)}</td><td><div class="btns">${btn('Edit','pricebook-edit',p.id,'small')}${btn('Archive','pricebook-archive',p.id,'small ghost')}</div></td></tr>`)):empty('No matching services','Add a service or change your search.'))}
function teamPage(){const rows=S.technicians.filter(t=>match(t.name+' '+t.specialty));return head('A great team makes the difference.','Manage your field roster, specializations, and upcoming workload.',btn('+ Add technician','technician-new','','primary'),'PEOPLE / FIELD TEAM')+`<div class="panel-grid">${rows.map((t,i)=>`<article class="service-card">${avatar(t.name,['','blue','rose'][i%3])}<h3>${esc(t.name)}</h3><p>${esc(t.specialty)}</p>${badge(t.active?'Active':'Inactive')}<p>${S.jobs.filter(j=>j.technician_id===t.id&&!['Completed','Canceled'].includes(j.status)).length} open visits<br>${S.jobs.filter(j=>j.technician_id===t.id&&j.status==='Completed').length} completed jobs</p>${btn(t.active?'Deactivate':'Reactivate','technician-toggle',t.id,'small')}</article>`).join('')}</div><p class="help">This is a field-team roster. Separate technician logins and account permissions are not enabled in this local workspace.</p>`}
function taskPage(){const rows=S.tasks.filter(t=>match(t.title+' '+(cid(t.customer_id)?.name||'')));return head('Nothing slips through the cracks.','Follow-ups, reminders, and the details that earn repeat business.',btn('+ Add task','task-new','','primary'),'WORKSPACE / TASKS')+`<div class="bottom-grid">${panel('To do',`${rows.filter(t=>!t.done).length} open tasks`,taskRows(rows.filter(t=>!t.done))||empty('All caught up','A good place to be.'))}${panel('Completed',`${rows.filter(t=>t.done).length} complete`,taskRows(rows.filter(t=>t.done))||empty('No completed tasks yet','Check off your first follow-up.'))}</div>`}
function reportPage(){const completed=S.jobs.filter(j=>j.status==='Completed');const revenue=S.payments.reduce((n,p)=>n+p.amount,0);const byTech=S.technicians.map(t=>({t,count:completed.filter(j=>j.technician_id===t.id).length}));const max=Math.max(1,...byTech.map(x=>x.count));return head('The bigger picture, made clear.','Understand your pipeline, service workload, and recorded collections.','','INSIGHTS / REPORTS')+`<div class="metrics">${metric('Collected revenue',usd(revenue),'All recorded payments')}${metric('Jobs completed',completed.length,'Across all technicians')}${metric('Approval rate',S.quotes.length?Math.round(S.quotes.filter(q=>q.status==='Approved').length/S.quotes.length*100)+'%':'—','Approved estimates / all estimates')}${metric('Active plans',S.agreements.filter(a=>a.status==='Active').length,'Maintenance agreements')}</div><div class="bottom-grid">${panel('Completed jobs by technician','All-time recorded workload.',`<div class="report-bars" role="img" aria-label="Completed jobs by technician">${byTech.map(x=>`<div class="bar-col"><b>${x.count}</b><i style="height:${x.count/max*95}px"></i><small>${esc(x.t.name.split(' ')[0])}</small></div>`).join('')}</div><div class="panel-body stat-list">${byTech.map(x=>`<div class="stat-row"><span>${esc(x.t.name)}</span><strong>${x.count} jobs</strong></div>`).join('')}</div>`)}${panel('Receivables','Every dollar has a place.',`<div class="panel-body stat-list"><div class="stat-row"><span>Total invoiced</span><strong>${usd(S.invoices.reduce((n,i)=>n+i.total,0))}</strong></div><div class="stat-row"><span>Recorded payments</span><strong>${usd(revenue)}</strong></div><div class="stat-row"><span>Outstanding</span><strong>${usd(S.invoices.reduce((n,i)=>n+balance(i),0))}</strong></div><div class="stat-row"><span>Overdue balance</span><strong>${usd(S.invoices.filter(i=>invStatus(i)==='Overdue').reduce((n,i)=>n+balance(i),0))}</strong></div></div>`)}</div>`+panel('Take your data with you','CSV exports use integer cents for monetary fields.',`<div class="panel-body btns">${['customers','requests','quotes','jobs','invoices','payments','equipment','agreements','time_entries','expenses','inventory','stock_movements'].map(t=>`<a class="btn small" href="/api/export?table=${t}" download="${t}.csv">↓ ${t[0].toUpperCase()+t.slice(1)}</a>`).join('')}</div>`)+panel('Workspace activity','A timestamped trail of changes.',S.activities.length?table(['ACTION','RECORD','WHEN'],S.activities.slice().reverse().slice(0,100).map(a=>`<tr><td>${esc(activityName(a.action))}</td><td>#${a.record_id}</td><td>${esc(new Date(a.created).toLocaleString('en-US',{timeZone:S.timezone}))}</td></tr>`)):empty('A fresh start','Your changes will appear here.'))}
function settingsPage(){const b=S.settings[0];return head('Make it your workspace.','Company details, estimate defaults, and payment terms.','','WORKSPACE / SETTINGS')+`<div class="content-grid"><div>${panel('Company & billing defaults','Used on invoices and new estimates.',`<form id="entry" data-kind="settings" class="panel-body"><div class="form-grid">${field('Company name','company','text',b.company,'required maxlength="200"',true)}${field('Office email','email','email',b.email,'required')}${field('Office phone','phone','tel',b.phone,'required')}${field('Business address','address','text',b.address,'required',true)}${field('Default tax rate (%)','tax','number',b.tax_bps/100,'min="0" max="20" step="0.01" required')}${field('Invoice payment terms (days)','invoice_days','number',b.invoice_days,'min="1" max="90" step="1" required')}</div><p class="help">USD · America/Los_Angeles. Confirm applicable tax rules for each job; the default does not determine tax liability.</p><div class="error" role="alert"></div><div class="form-actions"><button class="btn primary" type="submit">Save settings</button></div></form>`)}</div><aside>${panel('Backups & recovery','Your records and attachments, together.',`<div class="panel-body"><p class="muted">A verified daily backup is created when this workspace starts. Download another recovery point whenever you need it.</p><a class="btn" href="/api/backup" download>Download workspace backup</a><p class="help">Includes all records and attachments. Restore instructions are in the START HERE guide. Existing data is preserved before restoring.</p></div>`)}${panel('Connections','Current integration status.',`<div class="panel-body">${[['Card payments','Not connected. Record payments received through another channel.'],['Email & SMS','Drafts only. Messages are saved locally and can be copied.'],['Accounting','CSV export available. QuickBooks sync is not connected.'],['Online customer portal','Local customer-view preview available on estimates and invoices. No public portal is hosted.']].map(([t,p])=>`<div class="integration"><strong>${t}</strong><p>${p}</p></div>`).join('')}</div>`)}</aside></div>`}

function elapsed(entry){const seconds=Math.max(0,Math.floor((new Date(entry.stopped||Date.now())-new Date(entry.started))/1000));return `${Math.floor(seconds/3600)}h ${Math.floor(seconds%3600/60)}m`}
function timesheetPage(){const rows=S.time_entries.filter(e=>match(S.jobs.find(j=>j.id===e.job_id).title+' '+tid(e.technician_id).name));return head('Time well spent.','Track field work by technician and job. Starting a job starts its timer.',btn('Refresh','refresh')+btn('+ Record work time','time-new','','primary'),'OPERATIONS / TIME TRACKING')+panel('Work log',`${rows.filter(e=>!e.stopped).length} timers running`,rows.length?table(['TECHNICIAN','JOB','STARTED','DURATION','STATUS',''],rows.slice().reverse().map(e=>`<tr><td>${esc(tid(e.technician_id).name)}</td><td><button class="link" data-act="job" data-id="${e.job_id}">${esc(S.jobs.find(j=>j.id===e.job_id).title)}</button></td><td>${fmt(e.started)} · ${new Date(e.started).toLocaleTimeString('en-US',{timeZone:S.timezone,hour:'numeric',minute:'2-digit'})}</td><td>${elapsed(e)}</td><td>${badge(e.stopped?'Recorded':'Running')}</td><td>${!e.stopped?btn('Stop timer','time-stop',e.id,'small'):''}</td></tr>`)):empty('Ready when the work begins','Start a job or record a past work period.'))+`<p class="help">Time is recorded for operations, not payroll. Refresh to update running durations. Completing or canceling a job stops its running timer.</p>`}
function expensePage(){const rows=S.expenses.filter(e=>match(e.vendor+' '+e.description+' '+S.jobs.find(j=>j.id===e.job_id).title));return head('Keep the cost of a job in view.','Record parts purchases, travel, and other job expenses.',btn('+ Record expense','expense-new','','primary'),'FINANCES / EXPENSES')+`<div class="metrics">${metric('Recorded expenses',usd(rows.reduce((n,e)=>n+e.amount,0)),'All recorded job expenses')}${metric('Expense entries',rows.length,'Vendor receipts and job costs')}${metric('Jobs with expenses',new Set(rows.map(e=>e.job_id)).size,'Costs tied to service work')}${metric('Categories',new Set(rows.map(e=>e.category)).size,'Parts, travel, and other costs')}</div>`+panel('Expense ledger','Receipts can be attached to the corresponding job.',rows.length?table(['DATE','VENDOR / DESCRIPTION','JOB','CATEGORY','AMOUNT'],rows.slice().reverse().map(e=>`<tr><td>${fmt(e.incurred)}</td><td><strong>${esc(e.vendor)}</strong><small>${esc(e.description)}</small></td><td><button class="link" data-act="job" data-id="${e.job_id}">JOB-${e.job_id}</button></td><td>${esc(e.category)}</td><td>${usd(e.amount)}</td></tr>`)):empty('No expenses recorded','Add a job cost to start tracking.'))}
function inventoryPage(){const rows=S.inventory.filter(p=>match(p.name+' '+p.sku));return head('The right part, ready to go.','Track shop inventory and record the parts used on a service call.',btn('+ Add stock item','inventory-new','','primary'),'OPERATIONS / PARTS INVENTORY')+panel('Parts on hand',`${rows.filter(p=>p.quantity<=p.reorder_at).length} items at or below their reorder point`,table(['PART / SKU','ON HAND','REORDER AT','UNIT COST','STATUS',''],rows.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.sku)}</small></td><td>${p.quantity}</td><td>${p.reorder_at}</td><td>${usd(p.unit_cost)}</td><td>${badge(p.quantity<=p.reorder_at?'Low stock':'In stock')}</td><td>${btn('Stock movement','inventory-move',p.id,'small')}</td></tr>`)))+panel('Stock history','Job usage and stock adjustments are recorded here.',S.stock_movements.length?table(['WHEN','PART','CHANGE','JOB / REASON'],S.stock_movements.slice().reverse().map(m=>`<tr><td>${fmt(m.created)}</td><td>${esc(S.inventory.find(p=>p.id===m.inventory_id).name)}</td><td>${m.quantity>0?'+':''}${m.quantity}</td><td>${m.job_id?'JOB-'+m.job_id+' · ':''}${esc(m.reason)}</td></tr>`)):empty('No stock movements yet','Opening sample quantities are shown above.'))}
function jobOperations(j){const running=S.time_entries.find(t=>t.job_id===j.id&&!t.stopped),entries=S.time_entries.filter(t=>t.job_id===j.id),expenses=S.expenses.filter(e=>e.job_id===j.id);return `<section class="detail-section"><h3>Time & job costs</h3><p class="muted">${entries.length} work periods · ${usd(expenses.reduce((n,e)=>n+e.amount,0))} expenses recorded</p><div class="btns">${j.status==='In progress'?(running?btn('Stop work timer','time-stop',running.id,'small'):btn('Resume work timer','time-start',j.id,'small')):''}${btn('Record expense','job-expense',j.id,'small')}${j.status==='In progress'?btn('Use a part','job-part',j.id,'small'):''}</div></section>`}
function openModal(title,body,eyebrow='AIRFRAME / WORKSPACE'){$('#modal').innerHTML=`<div class="modal-head"><div><div class="eyebrow">${eyebrow}</div><h2 id="modal-title">${title}</h2></div><button class="modal-close" data-act="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>`;if(!$('#dialog').open)$('#dialog').showModal();$('#dialog').scrollTop=0}
function form(title,kind,body,id='',submit='Save'){openModal(title,`<form id="entry" data-kind="${kind}" data-id="${id}"><div class="form-grid">${body}</div><div class="error" role="alert"></div><div class="form-actions">${btn('Cancel','close')}<button class="btn primary" type="submit">${submit}</button></div></form>`)}
function propertyOptions(customer,selected){return option('','Primary address',selected)+S.properties.filter(p=>p.customer_id===Number(customer)).map(p=>option(p.id,`${p.label} — ${p.address}`,selected)).join('')}
function quoteLines(q){return table(['DESCRIPTION','QTY','UNIT PRICE','AMOUNT'],q.items.map(i=>`<tr><td>${esc(i.description)}</td><td>${i.quantity}</td><td>${usd(i.unit_cents)}</td><td>${usd(i.quantity*i.unit_cents)}</td></tr>`))+`<div class="total-box">Subtotal ${usd(q.subtotal)}<br>Discount −${usd(q.discount)}<br>Tax (${q.tax_bps/100}%) ${usd(q.total-q.subtotal+q.discount)}<strong>${usd(q.total)}</strong></div>`}
function customerDetail(id){const c=cid(id);const props=S.properties.filter(p=>p.customer_id===c.id);const equipment=S.equipment.filter(e=>e.customer_id===c.id);const notes=S.notes.filter(n=>n.customer_id===c.id);const files=S.files.filter(f=>f.customer_id===c.id);const messages=S.messages.filter(m=>m.customer_id===c.id);openModal(esc(c.name),`${badge(c.active?'Active':'Archived')}<div class="detail-title">Every visit builds a relationship.</div><div class="detail-grid"><div class="detail-box"><label>CONTACT</label><span>${esc(c.email)}<br>${esc(c.phone)}</span></div><div class="detail-box"><label>PRIMARY ADDRESS</label><span>${esc(c.address)}</span></div></div><p class="muted">${esc(c.notes)}</p><div class="btns">${btn('Edit customer','customer-edit',id,'small')}${btn('New estimate','estimate-customer',id,'small primary')}${btn('Draft message','message-new',id,'small')}${btn(c.active?'Archive':'Restore','customer-archive',id,'small ghost')}</div><section class="detail-section"><div class="section-top"><h3>Properties</h3>${btn('+ Add property','property-new',id,'small')}</div>${props.map(p=>`<div class="detail-box"><label>${esc(p.label)}</label><span>${esc(p.address)}</span><p class="help">${esc(p.access_notes)}</p></div>`).join('')||'<p class="muted">No additional properties.</p>'}</section><section class="detail-section"><div class="section-top"><h3>Equipment</h3>${btn('+ Add equipment','equipment-customer',id,'small')}</div>${equipment.length?table(['UNIT','MODEL / SERIAL','NEXT SERVICE'],equipment.map(e=>`<tr><td>${esc(e.brand)} ${esc(e.kind)}</td><td>${esc(e.model)}<small>${esc(e.serial)}</small></td><td>${fmt(e.next_service)}</td></tr>`)):'<p class="muted">No equipment recorded.</p>'}</section><section class="detail-section"><h3>Service history</h3>${S.jobs.some(j=>j.customer_id===c.id)?table(['JOB','DATE','STATUS'],S.jobs.filter(j=>j.customer_id===c.id).slice().reverse().map(j=>`<tr class="clickable" tabindex="0" role="button" data-act="job" data-id="${j.id}"><td>${esc(j.title)}</td><td>${fmt(j.start)}</td><td>${badge(j.status)}</td></tr>`)):'<p class="muted">No visits yet.</p>'}</section><section class="detail-section"><h3>Estimates & invoices</h3><div class="btns">${S.quotes.filter(q=>q.customer_id===c.id).map(q=>btn(`EST-${q.id} · ${usd(q.total)}`,'estimate',q.id,'small')).join('')}${S.invoices.filter(i=>i.customer_id===c.id).map(i=>btn(`INV-${i.id} · ${usd(balance(i))} due`,'invoice',i.id,'small')).join('')||'<p class="muted">No financial records yet.</p>'}</div></section><section class="detail-section"><div class="section-top"><h3>Notes</h3>${btn('+ Add note','note-new',id,'small')}</div>${notes.map(n=>`<div class="note">${esc(n.body)}<small>${fmt(n.created)}${n.job_id?' · JOB-'+n.job_id:''}</small></div>`).join('')||'<p class="muted">Add access instructions, preferences, or service notes.</p>'}</section><section class="detail-section"><div class="section-top"><h3>Photos & documents</h3>${btn('+ Upload','file-new',id,'small')}</div>${files.map(f=>`<div class="note"><a class="link" href="/files/${f.id}" download>${esc(f.name)} ↓</a><small>${Math.round(f.size/1024)} KB · ${fmt(f.created)}</small></div>`).join('')||'<p class="muted">PNG, JPEG, or PDF · up to 2 MB each.</p>'}</section><section class="detail-section"><h3>Message drafts</h3>${messages.map(m=>`<div class="note"><strong>${esc(m.channel)} · ${esc(m.subject)}</strong><small>Draft · not sent · ${fmt(m.created)}</small>${esc(m.body)}<div>${btn('Copy draft','message-copy',m.id,'small')}</div></div>`).join('')||'<p class="muted">No saved drafts.</p>'}</section>`,'CUSTOMER / DETAILS')}
function estimateDetail(id,client=false){const q=S.quotes.find(q=>q.id===Number(id));const c=cid(q.customer_id),job=S.jobs.find(j=>j.quote_id===q.id);openModal(client?'Customer view preview':`Estimate EST-${String(q.id).padStart(4,'0')}`,`<div class="invoice-paper"><div class="invoice-heading"><div><h2>${esc(S.settings[0].company)}</h2><p>${esc(S.settings[0].address)}<br>${esc(S.settings[0].phone)}</p></div><div><h3>ESTIMATE / ${String(q.id).padStart(4,'0')}</h3><p>Prepared ${fmt(q.created)}<br>${esc(c.name)}<br>${esc(c.address)}</p>${badge(q.status)}</div></div><h3>${esc(q.title)}</h3>${quoteLines(q)}<p>Prepared for review. Approval and scheduling are recorded by your service team.</p></div><div class="form-actions print-hide">${client?btn('Back to estimate','estimate',q.id):`${btn('Client view','estimate-client',q.id)}${btn('Print / save PDF','print')}${q.status==='Draft'?btn('Edit draft','estimate-edit',q.id)+btn('Record approval','estimate-approve',q.id,'primary')+btn('Decline','estimate-decline',q.id,'danger'):''}${q.status==='Approved'&&!job?btn('Schedule visit','schedule-quote',q.id,'primary'):''}${job?btn('View job','job',job.id):''}`}</div>`,'SALES / ESTIMATE')}
function jobDetail(id){const j=S.jobs.find(j=>j.id===Number(id)),q=S.quotes.find(q=>q.id===j.quote_id),inv=S.invoices.find(i=>i.job_id===j.id);const checks=j.checklist.length?j.checklist:[{label:'Inspect system and record diagnosis',done:false},{label:'Complete service and test operation',done:false},{label:'Review findings with customer',done:false}];openModal(esc(j.title),`${badge(j.status)} <span class="priority ${j.priority}">${j.priority}</span><div class="detail-grid detail-section"><div class="detail-box"><label>CUSTOMER & PROPERTY</label><span>${esc(cid(j.customer_id).name)}<br>${esc(jobAddress(j))}</span></div><div class="detail-box"><label>VISIT / PACIFIC TIME</label><span>${fmt(j.start)} · ${time(j.start)}–${time(j.end)}<br>${esc(tid(j.technician_id).name)}</span></div></div><div class="btns detail-section">${nextStatus(j)&&j.status!=='Canceled'?btn({'En route':'Mark en route','In progress':'Start job',Completed:'Complete job'}[nextStatus(j)],'job-next',j.id,'primary'):''}${['Scheduled','En route'].includes(j.status)?btn('Reschedule','job-reschedule',j.id):''}${j.status==='Completed'&&!inv?btn('Create invoice','job-invoice',j.id,'primary'):''}${inv?btn('Open invoice','invoice',inv.id):''}${!['Completed','Canceled'].includes(j.status)?btn('Cancel job','job-cancel',j.id,'danger'):''}</div><section class="detail-section"><h3>Work checklist & service notes</h3><form id="entry" data-kind="job-notes" data-id="${j.id}">${checks.map(x=>`<label class="inline-check"><input type="checkbox" name="check" data-label="${esc(x.label)}" ${x.done?'checked':''}>${esc(x.label)}</label>`).join('')}${textArea('Findings, work performed, and recommendations','notes',j.notes)}<div class="error" role="alert"></div><div class="form-actions"><button type="submit" class="btn">Save work notes</button></div></form></section><section class="detail-section"><div class="section-top"><h3>Attached photos & documents</h3>${btn('+ Upload','job-file',j.id,'small')}</div>${S.files.filter(f=>f.job_id===j.id).map(f=>`<div class="note"><a href="/files/${f.id}" class="link" download>${esc(f.name)} ↓</a></div>`).join('')||'<p class="muted">Add before/after photos or service documents.</p>'}</section>${jobOperations(j)}<section class="detail-section"><h3>Approved estimate</h3>${quoteLines(q)}</section>`,'JOB / '+String(j.id).padStart(4,'0'))}
function invoiceDetail(id,client=false){const i=S.invoices.find(i=>i.id===Number(id)),j=S.jobs.find(j=>j.id===i.job_id),q=S.quotes.find(q=>q.id===j.quote_id),c=cid(i.customer_id);openModal(client?'Customer view preview':`Invoice INV-${String(i.id).padStart(4,'0')}`,`<div class="invoice-paper"><div class="invoice-heading"><div><h2>${esc(S.settings[0].company)}</h2><p>${esc(S.settings[0].address)}<br>${esc(S.settings[0].email)}<br>${esc(S.settings[0].phone)}</p></div><div><h3>INVOICE / ${String(i.id).padStart(4,'0')}</h3><p>Issued ${fmt(i.created)}<br>Due ${fmt(i.due)}<br>${esc(c.name)}<br>${esc(c.address)}</p>${badge(invStatus(i))}</div></div><h3>${esc(j.title)}</h3>${quoteLines(q)}<div class="total-box">Payments received ${usd(totalPaid(i))}<strong>Balance due ${usd(balance(i))}</strong></div><p>Contact the office to arrange payment. This preview does not collect or charge a card.</p></div><section class="detail-section"><h3>Payment history</h3>${S.payments.some(p=>p.invoice_id===i.id)?table(['DATE','METHOD','REFERENCE','AMOUNT'],S.payments.filter(p=>p.invoice_id===i.id).map(p=>`<tr><td>${fmt(p.created)}</td><td>${esc(p.method)}</td><td>${esc(p.reference)}</td><td>${usd(p.amount)}</td></tr>`)):'<p class="muted">No payments recorded.</p>'}</section><div class="form-actions print-hide">${client?btn('Back to invoice','invoice',i.id):`${btn('Client view','invoice-client',i.id)}${btn('Print / save PDF','print')}${balance(i)>0?btn('Record payment','payment-new',i.id,'primary'):''}`}</div>`,'FINANCES / INVOICE')}

function scheduleForm(qid,jid){const job=S.jobs.find(j=>j.id===Number(jid));const eligible=S.quotes.filter(q=>q.status==='Approved'&&!S.jobs.some(j=>j.quote_id===q.id));if(!job&&!eligible.length){openModal('Ready for the next visit?',empty('Approve an estimate first','An approved estimate keeps scope and price connected to the job.')+`<div class="form-actions">${btn('New estimate','estimate-new','','primary')}</div>`);return}const q=job?S.quotes.find(q=>q.id===job.quote_id):eligible.find(q=>q.id===Number(qid))||eligible[0];form(job?'Reschedule visit':'Schedule a service visit',job?'reschedule':'schedule',`${job?`<div class="field full"><strong>${esc(q.title)}</strong></div>`:select('Approved estimate','quote_id',eligible.map(x=>option(x.id,`${cid(x.customer_id).name} — ${x.title}`,q.id)).join(''),true)}${select('Technician','technician_id',S.technicians.filter(t=>t.active).map(t=>option(t.id,t.name,job?.technician_id)).join(''))}${select('Priority','priority',['Normal','High','Urgent'].map(v=>option(v,v,job?.priority)).join(''))}${field('Start · Pacific time','start','datetime-local',job?.start||dispatchDate+'T09:00','required')}${field('End · Pacific time','end','datetime-local',job?.end||dispatchDate+'T10:00','required')}<p class="help field full">Overlapping active visits for the same technician are blocked. Visits must start and end on the same day.</p>`,job?.id||'','Save visit')}
function estimateForm(customer,request,editId){const existing=S.quotes.find(q=>q.id===Number(editId));const r=S.requests.find(r=>r.id===Number(request));const c=Number(customer)||r?.customer_id||S.customers.find(c=>c.active)?.id;if(!c){openModal('Add a customer first',empty('No active customers','Add a customer before preparing an estimate.'));return}form(existing?'Edit draft estimate':'Build an estimate','estimate',`${customerSelect(c)}${select('Service property','property_id',propertyOptions(c,existing?.property_id))}${field('Estimate title','title','text',existing?.title||r?.title||'','required maxlength="200"',true)}${r?`<input type="hidden" name="request_id" value="${r.id}">`:''}<div class="field full">Line items<div class="line-items" id="line-items">${existing?existing.items.map(i=>lineItem(i)).join(''):lineItem()}</div><div class="btns" style="margin-top:10px">${btn('+ Custom item','line-add','','small')}${select('Add from price book','pricebook_pick',option('','Select a service…')+S.pricebook.filter(p=>p.active).map(p=>option(p.id,`${p.name} · ${usd(p.unit_cents)}`)).join(''))}</div></div>${field('Discount ($)','discount','number',existing?(existing.discount/100).toFixed(2):'0','min="0" step="0.01" required')}${field('Sales tax (%)','tax','number',(existing?.tax_bps??S.settings[0].tax_bps)/100,'min="0" max="20" step="0.01" required')}<div class="field full"><p class="help">Save a draft, then record customer approval before scheduling. Saving does not send an email.</p></div>`,existing?.id||'','Save estimate');updateEstimateTotal()}
function lineItem(p){return `<div class="line-item"><input name="description" aria-label="Item description" placeholder="Service or part description" value="${esc(p?.name||p?.description||'')}" maxlength="200" required><input name="quantity" aria-label="Quantity" type="number" min="1" max="999" step="1" value="${p?.quantity||1}" required><input name="unit_price" aria-label="Unit price" type="number" min="0" max="1000000" step="0.01" value="${p?(p.unit_cents/100).toFixed(2):''}" placeholder="0.00" required><button class="remove" data-act="line-remove" type="button" aria-label="Remove line item">×</button></div>`}
function updateEstimateTotal(){const f=$('form[data-kind="estimate"]');if(!f)return;const subtotal=$$('.line-item',f).reduce((n,row)=>n+(Number($('[name=unit_price]',row).value)||0)*(Number($('[name=quantity]',row).value)||0),0);const discount=Number(f.elements.discount.value)||0,tax=Number(f.elements.tax.value)||0;let box=$('.estimate-preview',f);if(!box){box=document.createElement('div');box.className='total-box estimate-preview';f.insertBefore(box,$('.form-actions',f))}box.textContent='Estimated total '+usd(Math.round((subtotal-discount)*(1+tax/100)*100))}
function requestDetail(id){const r=S.requests.find(r=>r.id===Number(id));openModal(esc(r.title),`${badge(r.status)} <span class="priority ${r.priority}">${r.priority}</span><p class="muted">${esc(cid(r.customer_id).name)} · ${esc(r.source)} · ${fmt(r.created)}</p><div class="note">${esc(r.description)}</div><div class="form-actions">${btn('View customer','customer',r.customer_id)}${r.status==='New'?btn('Mark contacted','request-contact',r.id):''}${!['Lost','Won'].includes(r.status)?btn('Close as lost','request-lost',r.id,'danger'):''}${btn('Prepare estimate','estimate-request',r.id,'primary')}</div>`,'SERVICE / REQUEST')}

async function action(act,id,el){if(['request-new','agreement-new','equipment-new'].includes(act)&&!S.customers.some(c=>c.active)){openModal('Add a customer first',empty('No active customers','Add or restore a customer to continue.')+`<div class="form-actions">${btn('Add customer','customer-new','','primary')}</div>`);return}switch(act){
 case 'close':$('#dialog').close();return;
 case 'refresh':await load();toast('Workspace refreshed.');return;
 case 'customer':customerDetail(id);return;
 case 'job':jobDetail(id);return;
 case 'estimate':estimateDetail(id);return;
 case 'invoice':invoiceDetail(id);return;
 case 'request':requestDetail(id);return;
 case 'estimate-client':estimateDetail(id,true);return;
 case 'invoice-client':invoiceDetail(id,true);return;
 case 'print':window.print();return;
 case 'dispatch-mode':dispatchMode=id;render();return;
 case 'dispatch-today':dispatchDate=S.today;render();return;
 case 'dispatch-latest':dispatchDate=S.jobs.map(j=>j.start.slice(0,10)).sort().at(-1)||S.today;jobFilter='All';location.hash='dispatch';return;
 case 'job-filter':jobFilter=id;render();return;
 case 'customer-filter':customerFilter=id;render();return;
 case 'customer-new':case 'customer-edit':{const c=act==='customer-edit'?cid(id):{};form(c.id?'Edit customer':'A new customer relationship','customer',`${field('Full name or business','name','text',c.name||'','required maxlength="200"',true)}${field('Email','email','email',c.email||'','required maxlength="200"')}${field('Phone','phone','tel',c.phone||'','required maxlength="200"')}${field('Primary service address','address','text',c.address||'','required maxlength="200"',true)}${textArea('Customer preferences & access notes','notes',c.notes||'')}`,c.id||'','Save customer');return}
 case 'property-new':form('Add a service property','property',`<input type="hidden" name="customer_id" value="${id}">${field('Property label','label','text','','required maxlength="100"',true)}${field('Address','address','text','','required maxlength="300"',true)}${textArea('Access instructions','access_notes')}`);return;
 case 'request-new':form('Capture a service request','request',`${customerSelect()}${select('Source','source',['Phone','Website','Referral','Maintenance','Other'].map(v=>option(v,v)).join(''))}${field('What can we help with?','title','text','','required maxlength="200"',true)}${select('Priority','priority',['Normal','High','Urgent'].map(v=>option(v,v)).join(''))}${textArea('Issue, symptoms & customer needs','description','',true)}`,'','Save request');return;
 case 'estimate-new':estimateForm();return;
 case 'estimate-edit':{const q=S.quotes.find(q=>q.id===Number(id));estimateForm(q.customer_id,q.request_id,q.id);return}
 case 'estimate-customer':estimateForm(id);return;
 case 'estimate-request':estimateForm(null,id);return;
 case 'line-add':$('#line-items').insertAdjacentHTML('beforeend',lineItem());updateEstimateTotal();return;
 case 'line-remove':if($$('.line-item').length>1)el.closest('.line-item').remove();updateEstimateTotal();return;
 case 'schedule-new':scheduleForm();return;
 case 'schedule-quote':scheduleForm(id);return;
 case 'job-reschedule':scheduleForm(null,id);return;
 case 'equipment-new':case 'equipment-customer':{const c=Number(id)||S.customers[0]?.id;if(!c)throw Error('Add a customer first.');form('Add HVAC equipment','equipment',`${customerSelect(c)}${select('Service property','property_id',propertyOptions(c))}${select('Equipment type','kind',['Central AC','Heat pump','Gas furnace','Air handler','Mini-split','Rooftop unit','Boiler','Other'].map(v=>option(v,v)).join(''))}${field('Manufacturer','brand','text','','required maxlength="200"')}${field('Model','model','text','','required maxlength="200"')}${field('Serial number','serial','text','','required maxlength="200"')}${field('Next service date','next_service','date',S.today,'required')}`);return}
 case 'equipment-service':{const e=S.equipment.find(e=>e.id===Number(id));form('Update next service date','equipment-service',`${field('Next service date','next_service','date',e.next_service,'required',true)}`,id);return}
 case 'pricebook-new':case 'pricebook-edit':{const p=act==='pricebook-edit'?S.pricebook.find(p=>p.id===Number(id)):{};form(p.id?'Edit service':'Add a service or part','pricebook',`${field('Service or item name','name','text',p.name||'','required maxlength="150"',true)}${select('Category','category',['Service','Maintenance','Repair','Installation','Parts','Commercial'].map(v=>option(v,v,p.category)).join(''))}${field('Unit price ($)','unit_price','number',p.unit_cents!=null?(p.unit_cents/100).toFixed(2):'','required min="0" max="1000000" step="0.01"')}`,p.id||'');return}
 case 'agreement-new':form('Create a maintenance plan','agreement',`${customerSelect()}${field('Plan name','name','text','Comfort Care','required maxlength="150"')}${field('Price per visit ($)','unit_price','number','149.00','required min="0" step="0.01"')}${select('Visit frequency','interval_months',[[1,'Monthly'],[3,'Quarterly'],[6,'Every 6 months'],[12,'Annually']].map(([v,t])=>option(v,t,6)).join(''))}${field('Next visit due','next_visit','date',S.today,'required',true)}`,'','Create plan');return;
 case 'technician-new':form('Add a field technician','technician',`${field('Full name','name','text','','required maxlength="100"',true)}${field('Specialization','specialty','text','','required maxlength="100"',true)}`);return;
 case 'task-new':form('A little follow-up goes a long way','task',`${field('Task','title','text','','required maxlength="200"',true)}${field('Due date','due','date',S.today,'required')}${select('Related customer (optional)','customer_id',option('','No customer')+customers())}`,'','Save task');return;
 case 'note-new':form('Add a customer note','note',`<input type="hidden" name="customer_id" value="${id}">${textArea('Note','body','',true)}`);return;
 case 'message-new':form('Prepare a message','message',`<input type="hidden" name="customer_id" value="${id}"><div class="notice field full">Draft only. This message will be saved locally, not sent. Copy it into your email or messaging service.</div>${select('Channel','channel',['Email','SMS'].map(v=>option(v,v)).join(''))}${field('Subject (email)','subject','text','','maxlength="200"')}${textArea('Message','body','',true)}`,'','Save draft');return;
 case 'message-copy':{const m=S.messages.find(m=>m.id===Number(id));await navigator.clipboard.writeText((m.subject?m.subject+'\n\n':'')+m.body);toast('Draft copied. Nothing was sent.');return}
 case 'file-new':case 'job-file':{const job=act==='job-file'?S.jobs.find(j=>j.id===Number(id)):null;form('Attach a photo or document','file',`<input type="hidden" name="customer_id" value="${job?job.customer_id:id}">${job?`<input type="hidden" name="job_id" value="${job.id}">`:''}<label class="field full">Choose a file<input type="file" name="file" accept="image/png,image/jpeg,application/pdf" required></label><p class="help field full">PNG, JPEG, or PDF · maximum 2 MB. Files stay in this local workspace.</p>`,'','Upload file');return}
 case 'time-new':form('Record a past work period','time',`${select('Job / assigned technician','job_id',S.jobs.map(j=>option(j.id,`JOB-${j.id} — ${tid(j.technician_id).name} — ${j.title}`)).join(''),true)}${field('Start · Pacific time','started','datetime-local',S.today+'T08:00','required')}${field('End · Pacific time','stopped','datetime-local',S.today+'T09:00','required')}<p class="help field full">Past work only. Overlapping time for the same technician is blocked.</p>`,'','Save work time');return;
 case 'expense-new':case 'job-expense':form('Record a job expense','expense',`${select('Related job','job_id',S.jobs.map(j=>option(j.id,`JOB-${j.id} — ${j.title}`,id)).join(''),true)}${field('Vendor','vendor','text','','required maxlength="150"')}${select('Category','category',['Parts','Travel','Subcontractor','Equipment rental','Other'].map(v=>option(v,v)).join(''))}${field('Amount ($)','amount','number','','required min="0" step="0.01"')}${field('Expense date','incurred','date',S.today,'required')}${field('Description','description','text','','required maxlength="500"',true)}`,'','Record expense');return;
 case 'inventory-new':form('Add a part to inventory','inventory',`${field('Part name','name','text','','required maxlength="150"',true)}${field('SKU','sku','text','','required maxlength="80"')}${field('Unit cost ($)','unit_cost','number','','required min="0" step="0.01"')}${field('Opening quantity','quantity','number','0','required min="0" max="100000" step="1"')}${field('Reorder point','reorder_at','number','3','required min="0" max="100000" step="1"')}`);return;
 case 'inventory-move':case 'job-part':{const job=act==='job-part'?S.jobs.find(j=>j.id===Number(id)):null;const part=job?null:S.inventory.find(p=>p.id===Number(id));form(job?'Record parts used on this job':'Record a stock movement','inventory-move',`${select('Part','id',S.inventory.map(p=>option(p.id,`${p.sku} — ${p.name} (${p.quantity} on hand)`,part?.id)).join(''),true)}${job?`<input type="hidden" name="job_id" value="${job.id}">`:select('Job (optional; usage only)','job_id',option('','No job — stock adjustment')+S.jobs.filter(j=>j.status==='In progress').map(j=>option(j.id,j.title)).join(''),true)}${field('Stock change (+ receive / − consume)','quantity','number','-1','required min="-100000" max="100000" step="1"',true)}${field('Reason','reason','text',job?'Parts used during service':'','required maxlength="300"',true)}`,'','Save stock movement');return}
 case 'invoice-new':{const jobs=S.jobs.filter(j=>j.status==='Completed'&&!S.invoices.some(i=>i.job_id===j.id));if(!jobs.length){openModal('Invoice a completed job',empty('No uninvoiced completed jobs','Finish a job on the dispatch board first.'));return}form('Create an invoice','invoice',select('Completed job','job_id',jobs.map(j=>option(j.id,`${cid(j.customer_id).name} — ${j.title}`)).join(''),true),'','Create invoice');return}
 case 'payment-new':{const i=S.invoices.find(i=>i.id===Number(id));form('Record a payment received','payment',`<div class="notice field full">This records money already received. It does not charge a card or initiate a transfer. Outstanding: ${usd(balance(i))}.</div>${field('Amount received ($)','amount','number',(balance(i)/100).toFixed(2),`required min="0.01" max="${balance(i)/100}" step="0.01"`)}${select('Payment method','method',['Cash','Check','Bank transfer','Card (external)','Other'].map(v=>option(v,v)).join(''))}${field('Reference / check number','reference','text','','maxlength="200"',true)}`,id,'Record payment');return}
 default:await mutateAction(act,id,el);
}}
async function mutateAction(act,id,el){const n=Number(id);let route,data={id:n},message='Saved.',open;
 switch(act){case 'customer-archive':route='customers/archive';data.active=!cid(n).active;message=data.active?'Customer restored.':'Customer archived.';break;
 case 'estimate-approve':route='quotes/approve';message='Customer approval recorded.';break;
 case 'estimate-decline':route='quotes/decline';message='Estimate declined.';break;
 case 'request-contact':route='requests/status';data.status='Contacted';break;
 case 'request-lost':route='requests/status';data.status='Lost';break;
 case 'job-next':route='jobs/status';data.status=nextStatus(S.jobs.find(j=>j.id===n));open=['job',n];message='Job status updated.';break;
 case 'job-cancel':route='jobs/cancel';message='Job canceled.';break;
 case 'job-invoice':route='invoices';data={job_id:n};message='Invoice created.';break;
 case 'time-start':route='time/start';data={job_id:n};message='Work timer started.';break;
 case 'time-stop':route='time/stop';message='Work timer stopped.';break;
 case 'task-toggle':route='tasks/done';data.done=!S.tasks.find(t=>t.id===n).done;break;
 case 'pricebook-archive':route='pricebook/archive';message='Service archived.';break;
 case 'technician-toggle':route='technicians/active';data.active=!S.technicians.find(t=>t.id===n).active;break;
 case 'agreement-toggle':route='agreements/status';data.status=S.agreements.find(a=>a.id===n).status==='Active'?'Paused':'Active';break;
 case 'agreement-cancel':route='agreements/status';data.status='Canceled';break;
 case 'agreement-visit':route='agreements/visit';message='Maintenance visit estimate prepared. Schedule it next.';break;
 default:throw Error('This action is unavailable.');}
 if(el)el.disabled=true;
 try{const result=await api(route,data);await load();$('#dialog').close();toast(message);if(act==='job-invoice')invoiceDetail(result.id);else if(act==='agreement-visit')scheduleForm(result.quote_id);else if(open)jobDetail(open[1]);}
 finally{if(el)el.disabled=false}
}

document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(el){e.preventDefault();Promise.resolve(action(el.dataset.act,el.dataset.id,el)).catch(err=>toast(err.message,true));}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search').focus()}if(['Enter',' '].includes(e.key)&&e.target.matches('[role=button][data-act]')){e.preventDefault();e.target.click()}});
$('.mobile-menu').addEventListener('click',()=>document.body.classList.toggle('menu-open'));
$('#search').addEventListener('input',e=>{query=e.target.value;render()});
window.addEventListener('hashchange',setPage);
document.addEventListener('change',e=>{const t=e.target;if(t.id==='dispatch-date'){dispatchDate=t.value;render()}if(t.id==='dispatch-status'){jobFilter=t.value;render()}if(t.name==='customer_id'&&t.form?.elements.property_id){t.form.elements.property_id.innerHTML=propertyOptions(t.value)}if(t.name==='pricebook_pick'&&t.value){const p=S.pricebook.find(p=>p.id===Number(t.value));const rows=$$('.line-item',t.form);if(rows.length===1&&!$('[name=description]',rows[0]).value){rows[0].outerHTML=lineItem(p)}else $('#line-items').insertAdjacentHTML('beforeend',lineItem(p));t.value='';updateEstimateTotal()}});
document.addEventListener('input',e=>{if(e.target.closest('form[data-kind="estimate"]'))updateEstimateTotal()});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='entry')return;e.preventDefault();const error=$('.error',f);error.textContent='';const submit=$('[type=submit]',f);submit.disabled=true;try{
 const d=Object.fromEntries(new FormData(f)),kind=f.dataset.kind,id=Number(f.dataset.id);let route,payload=d,after;
 const num=k=>{if(d[k]!==undefined)d[k]=d[k]===''?null:Number(d[k])};
 ['customer_id','property_id','request_id','quote_id','technician_id','job_id','interval_months','invoice_days'].forEach(num);
 switch(kind){
 case 'customer':route=id?'customers/update':'customers';if(id)d.id=id;after='customer';break;
 case 'property':route='properties';after='customer';break;
 case 'request':route='requests';break;
 case 'estimate':route=id?'quotes/update':'quotes';if(id)d.id=id;d.tax_bps=Math.round(Number(d.tax)*100);delete d.tax;delete d.description;delete d.quantity;delete d.unit_price;delete d.pricebook_pick;d.items=$$('.line-item',f).map(row=>({description:$('[name=description]',row).value,quantity:Number($('[name=quantity]',row).value),unit_price:$('[name=unit_price]',row).value}));after='estimate';break;
 case 'schedule':route='jobs';after='job';break;
 case 'reschedule':route='jobs/reschedule';d.id=id;after='job';break;
 case 'equipment':route='equipment';break;
 case 'equipment-service':route='equipment/service';d.id=id;break;
 case 'pricebook':route='pricebook';if(id)d.id=id;break;
 case 'agreement':route='agreements';break;
 case 'technician':route='technicians';break;
 case 'task':route='tasks';break;
 case 'note':route='notes';after='customer';break;
 case 'message':route='messages';after='customer';break;
 case 'job-notes':route='jobs/notes';payload={id,notes:d.notes,checklist:$$('[name=check]',f).map(c=>({label:c.dataset.label,done:c.checked}))};after='job';break;
 case 'file':{route='files';const file=f.elements.file.files[0];if(!file||file.size>2000000)throw Error('Choose a file of at most 2 MB.');const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('Cannot read file.'));r.readAsDataURL(file)});payload={customer_id:d.customer_id,job_id:d.job_id||null,name:file.name,mime:file.type,content};after=d.job_id?'job':'customer';break}
 case 'time':route='time/manual';break;
 case 'expense':route='expenses';break;
 case 'inventory':route='inventory';d.quantity=Number(d.quantity);d.reorder_at=Number(d.reorder_at);break;
 case 'inventory-move':route='inventory/move';d.id=Number(d.id);d.quantity=Number(d.quantity);break;
 case 'invoice':route='invoices';after='invoice';break;
 case 'payment':route='invoices/pay';d.id=id;after='invoice';break;
 case 'settings':route='settings';d.tax_bps=Math.round(Number(d.tax)*100);delete d.tax;break;
 default:throw Error('Unknown form.');}
 const result=await api(route,payload);await load();$('#dialog').close();toast(kind==='message'?'Draft saved. Nothing was sent.':kind==='payment'?'Payment recorded. No charge was made.':'Saved successfully.');
 if(after==='customer')customerDetail(kind==='customer'?result.id:d.customer_id);if(after==='estimate')estimateDetail(result.id);if(after==='job')jobDetail(kind==='file'?d.job_id:result.id);if(after==='invoice')invoiceDetail(result.id);
 }catch(err){error.textContent=err.message}finally{submit.disabled=false}});
